@layer components {
  :where([data-control-family="timeline"][data-slot="root"]) {
    --cui-timeline-indicator-background: var(--background);
    --cui-timeline-indicator-foreground: var(--muted-foreground);
    --cui-timeline-indicator-size: calc(var(--spacing) * 4);
    --cui-timeline-running-foreground: var(--primary-text);
    --cui-timeline-waiting-foreground: var(--warning-text);
    --cui-timeline-success-foreground: var(--foreground);
    --cui-timeline-error-foreground: var(--destructive-text);
    --cui-timeline-separator-background: var(--border);
    --cui-timeline-separator-inline-size: 1px;
    --cui-timeline-title-foreground: var(--foreground);
    --cui-timeline-title-font-weight: var(--font-weight-medium);
    --cui-timeline-item-padding-block: calc(var(--spacing) * 5);
    --_timeline-line-height: calc(var(--spacing) * 5);
  }

  :where([data-control-family="timeline"][data-slot="item"]) {
    grid-template-columns: var(--cui-timeline-indicator-size) minmax(0, 1fr);
    column-gap: calc(var(--spacing) * 3);
    padding-block-end: var(--cui-timeline-item-padding-block);
  }

  :where([data-control-family="timeline"][data-slot="item"]:last-child) {
    padding-block-end: 0;
  }

  :where([data-control-family="timeline"][data-slot="content"]) {
    gap: calc(var(--spacing) * 1);
  }

  :where([data-control-family="timeline"][data-slot="meta"]) {
    margin-block-start: calc(var(--spacing) * 1);
    gap: calc(var(--spacing) * 1.5);
  }

  :where([data-control-family="timeline"][data-slot="indicator"]) {
    inline-size: var(--cui-timeline-indicator-size);
    block-size: var(--cui-timeline-indicator-size);
    margin-block-start: calc((var(--_timeline-line-height) - var(--cui-timeline-indicator-size)) / 2);
    border-radius: 9999px;
    background: var(--cui-timeline-indicator-background);
    color: var(--cui-timeline-indicator-foreground);
  }

  :where([data-control-family="timeline"][data-slot="indicator"] svg) {
    flex-shrink: 0;
    inline-size: var(--cui-timeline-indicator-size);
    block-size: var(--cui-timeline-indicator-size);
  }

  :where([data-control-family="timeline"][data-slot="item"][data-state="running"] [data-control-family="timeline"][data-slot="indicator"]) {
    color: var(--cui-timeline-running-foreground);
  }

  :where([data-control-family="timeline"][data-slot="item"][data-state="waiting"] [data-control-family="timeline"][data-slot="indicator"]) {
    color: var(--cui-timeline-waiting-foreground);
  }

  :where([data-control-family="timeline"][data-slot="item"][data-state="success"] [data-control-family="timeline"][data-slot="indicator"]) {
    color: var(--cui-timeline-success-foreground);
  }

  :where([data-control-family="timeline"][data-slot="item"][data-state="error"] [data-control-family="timeline"][data-slot="indicator"]) {
    color: var(--cui-timeline-error-foreground);
  }

  :where([data-control-family="timeline"][data-slot="separator"]) {
    inset-block-start: calc((var(--_timeline-line-height) + var(--cui-timeline-indicator-size)) / 2 + var(--spacing));
    inset-inline-start: calc((var(--cui-timeline-indicator-size) - var(--cui-timeline-separator-inline-size)) / 2);
    inline-size: var(--cui-timeline-separator-inline-size);
    background: var(--cui-timeline-separator-background);
  }

  :where([data-control-family="timeline"][data-slot="title"]) {
    color: var(--cui-timeline-title-foreground);
    font-size: var(--text-label);
    font-weight: var(--cui-timeline-title-font-weight);
    line-height: var(--_timeline-line-height);
    text-wrap: balance;
  }

  :where([data-control-family="timeline"][data-slot="description"]) {
    color: var(--muted-foreground);
    font-size: var(--text-label);
    line-height: var(--_timeline-line-height);
    text-wrap: pretty;
  }
}

@property --cui-timeline-indicator-background {
